package com.example.practice;

import org.jpos.iso.ISOException;
import org.jpos.iso.ISOMsg;
import org.jpos.iso.ISOUtil;
import org.jpos.iso.MUX;
import org.jpos.q2.iso.QMUX;
import org.jpos.util.NameRegistrar;

import java.util.concurrent.atomic.AtomicLong;

/**
 * The operations dashboard's probe for one host link. The dashboard calls {@link #check()} every
 * few seconds, for as long as the application runs, while Q2 deploys and redeploys the link.
 */
public class LinkStatus {
    public enum Status { NOT_DEPLOYED, DOWN, NO_ANSWER, UP }

    private final String muxName;
    private final long timeout;
    private final AtomicLong stans = new AtomicLong();

    public LinkStatus(String muxName, long timeout) {
        this.muxName = muxName;
        this.timeout = timeout;
    }

    public Status check() throws ISOException {
        MUX mux = find();
        if (mux == null)
            return Status.NOT_DEPLOYED;
        return probe(mux);
    }

    /** The multiplexer Q2 has deployed under {@code muxName} at this moment, or null if there is none. */
    MUX find() {
        try {
            return QMUX.getMUX(muxName);
        } catch (NameRegistrar.NotFoundException e) {
            return null;
        }
    }

    /** What the link behind {@code mux} is doing right now: DOWN, NO_ANSWER or UP. */
    Status probe(MUX mux) throws ISOException {
        if (!mux.isConnected())
            return Status.DOWN;
        ISOMsg response = mux.request(echo(), timeout);
        if (response == null)
            return Status.NO_ANSWER;
        return Status.UP;
    }

    /** An 0800 echo test with the next STAN of this probe. */
    ISOMsg echo() throws ISOException {
        ISOMsg m = new ISOMsg("0800");
        m.set(11, ISOUtil.zeropad((stans.incrementAndGet() - 1) % 999999 + 1, 6));
        m.set(70, "301");
        return m;
    }
}

import com.example.practice.LinkStatus;
import java.util.concurrent.atomic.AtomicBoolean;
import org.jdom2.Element;
import org.jpos.core.SimpleConfiguration;
import org.jpos.iso.ISOMsg;
import org.jpos.q2.iso.QMUX;
import org.jpos.space.LocalSpace;
import org.jpos.space.SpaceFactory;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) throws Exception {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            LocalSpace<String, Object> sp = (LocalSpace<String, Object>) SpaceFactory.getSpace("tspace:tryit");
            LinkStatus status = new LinkStatus("discover-mux", 400);
            System.out.println("before deploy: " + status.check());
            Element e = new Element("mux");
            e.addContent(new Element("space").setText("tspace:tryit"));
            e.addContent(new Element("in").setText("discover-receive"));
            e.addContent(new Element("out").setText("discover-send"));
            e.addContent(new Element("ready").setText("discover-channel.ready"));
            QMUX q = new QMUX();
            q.setName("discover-mux");
            q.setPersist(e);
            q.setConfiguration(new SimpleConfiguration());
            AtomicBoolean silent = new AtomicBoolean();
            try {
                q.init();
                q.start();
                System.out.println("deployed, link down: " + status.check());
                sp.addListener("discover-send", (key, value) -> {
                    ISOMsg request = (ISOMsg) sp.inp(key);
                    if (request != null && !silent.get())
                        sp.out("discover-receive", answer(request));
                });
                sp.out("discover-channel.ready", new java.util.Date());
                System.out.println("link up, host answers: " + status.check());
                silent.set(true);
                System.out.println("link up, host silent: " + status.check());
            } finally {
                q.stop();
                q.destroy();
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    private static ISOMsg answer(ISOMsg request) {
        try {
            ISOMsg response = (ISOMsg) request.clone();
            response.setResponseMTI();
            response.set(39, "00");
            return response;
        } catch (Exception ex) {
            throw new IllegalStateException(ex);
        }
    }
}

